/* Offline dashboard. Load from file:// via embedded board.js generated by the official pipeline, or serve locally. */
(async()=>{
const tbody=document.querySelector("#rows"),search=document.querySelector("#search"),chain=document.querySelector("#chain"),sort=document.querySelector("#sort"),count=document.querySelector("#count"),detail=document.querySelector("#detail");
let data=[];
try{
 const response=await fetch("./board.json");
 if(!response.ok)throw new Error("board.json unavailable");
 const raw=await response.json();data=Array.isArray(raw)?raw:(raw.rows||raw.protocols||raw.watchlist||raw.board||[]);
}catch(e){count.textContent="Unable to load board.json. Use a local static server if your browser blocks file:// JSON loading.";return;}
const val=(r,...keys)=>{for(const k of keys)if(r[k]!=null)return String(r[k]);return""};
const name=r=>val(r,"name","protocol","protocolName");
const ch=r=>val(r,"chain","chains","network");
const cat=r=>val(r,"category","type","sector");
const value=r=>val(r,"impliedValue","implied_value","impliedFdv","implied_fdv","valuation");
const farm=r=>{let x=r.farmPlan??r.farm_plan??r.farm??"";return Array.isArray(x)?x.join("\n"):typeof x==="object"?JSON.stringify(x,null,2):String(x)};
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const chains=[...new Set(data.map(ch).filter(Boolean))].sort();for(const c of chains){let o=document.createElement("option");o.value=c;o.textContent=c;chain.append(o)}
function open(r){document.querySelector("#detail-content").innerHTML=`<div class="eyebrow">PROTOCOL DOSSIER</div><h2>${esc(name(r))}</h2><p class="muted">Snapshot-derived research · verify assumptions before acting</p><div class="detail-grid"><div><span>CHAIN</span><strong>${esc(ch(r)||"Not specified")}</strong></div><div><span>CATEGORY</span><strong>${esc(cat(r)||"Not specified")}</strong></div><div><span>IMPLIED VALUE</span><strong>${esc(value(r))}</strong></div><div><span>TOKEN STATUS</span><strong>${esc(val(r,"tokenStatus","token_status")||"Pre-token watchlist")}</strong></div></div><h3>Participation / farming plan</h3><div class="farm">${esc(farm(r))}</div><p class="muted">Values are estimates, not guarantees. Participation may entail fees and risk.</p>`;detail.showModal()}
function render(){const q=search.value.trim().toLowerCase(),c=chain.value;let rows=data.filter(r=>(!c||ch(r)===c)&&(!q||[name(r),ch(r),cat(r),farm(r)].join(" ").toLowerCase().includes(q)));if(sort.value==="name")rows.sort((a,b)=>name(a).localeCompare(name(b)));if(sort.value==="value")rows.sort((a,b)=>{const n=r=>Number(value(r).replace(/[^0-9.]/g,""))||0;return n(b)-n(a)});count.textContent=`${rows.length} of ${data.length} protocols`;tbody.replaceChildren();rows.forEach((r,i)=>{const tr=document.createElement("tr");tr.tabIndex=0;tr.innerHTML=`<td class="muted">${i+1}</td><td>${esc(name(r))}</td><td><span class="pill">${esc(ch(r)||"—")}</span></td><td class="muted">${esc(cat(r)||"—")}</td><td>${esc(value(r))}</td><td><button class="view">View dossier →</button></td>`;tr.addEventListener("click",()=>open(r));tr.addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();open(r)}});tbody.append(tr)})}
[search,chain,sort].forEach(x=>x.addEventListener("input",render));document.querySelector("#close").onclick=()=>detail.close();render();
})();